static int equal(const void*a,const void*b,unsigned n){const uint8_t*p=a,*q=b;uint32_t d=0;for(unsigned i=0;i<n;i++)d|=p[i]^q[i];return !d;}
static int identity(const struct tr_request*a,const struct tr_request*b){return a&&b&&a->version==7&&b->version==7&&a->pid==b->pid&&a->ui_tid==b->ui_tid&&a->start==b->start&&a->major==b->major&&a->minor==b->minor&&a->inode==b->inode&&a->base==b->base&&a->uid==b->uid&&a->gid==b->gid&&a->mode==b->mode&&equal(a->nonce,b->nonce,16)&&equal(a->boot,b->boot,40);}
static int binding_ok(const struct sp_binding*b){const struct tr_api*a=b->table;return a&&b->base&&b->getter&&b->autostart&&a->version==7&&a->bytes==sizeof*a&&a->build==TR_BUILD&&a->prepare&&a->query&&a->action&&a->stop&&a->discover;}
static int description_ok(const struct tr_probe*p,const struct sp_binding*b,const struct tr_discovery*d,int rc){if(d->abi!=7||d->bytes!=sizeof*d||d->build!=TR_BUILD||d->status!=(uint32_t)rc||(d->flags&~63u))return 0;if(rc)return rc==1||rc==2||rc==21||rc==23;if(!(d->flags&1)||d->core_base!=b->base||d->api_entry!=b->getter||d->autoload_entry!=b->autostart||d->identity.version!=7||d->identity.pid!=p->pid||d->identity.start!=p->start||(p->ui_tid&&d->identity.ui_tid!=p->ui_tid)||!equal(d->identity.boot,p->boot,40)||!d->identity.ui_tid||d->identity.ui_tid==d->identity.pid||!d->identity.inode||(d->origin!=1&&d->origin!=2)||((d->flags&16)!=0)!=(d->origin==2))return 0;uint32_t any=0;for(unsigned i=0;i<16;i++)any|=d->identity.nonce[i];return any!=0;}
int sp_release(const struct sp_ports*p,struct sp_selection*s){if(!p||!p->close||!s)return 20;void*h=s->handle;s->handle=0;s->binding=(struct sp_binding){0};if(h&&p->close(p->context,h)){s->close_uncertain=1;return AS_CLOSE_UNCERTAIN;}return 0;}
int sp_select(const struct sp_ports*p,const struct tr_probe*probe,const struct tr_request*q,enum sp_mode mode,struct sp_selection*out){if(out)*out=(struct sp_selection){0};if(!p||!probe||!out||!p->open||!p->binding||!p->close||(unsigned)mode>SP_PREPARE||probe->abi!=7||probe->bytes!=sizeof*probe)return 20;*out=(struct sp_selection){0};struct sp_selection slots[2]={{0}};int rc[2]={21,21},result=21;unsigned owners=0,chosen=2;
 for(unsigned i=0;i<2;i++){slots[i].kind=i;slots[i].handle=p->open(p->context,i,1);if(!slots[i].handle)continue;if(!p->binding(p->context,slots[i].handle,&slots[i].binding)||!binding_ok(&slots[i].binding)){result=SP_BAD_PROVIDER;goto done;}rc[i]=slots[i].binding.table->discover(probe,&slots[i].discovery);if(!description_ok(probe,&slots[i].binding,&slots[i].discovery,rc[i])){result=SP_BAD_PROVIDER;goto done;}if(!rc[i]){owners++;chosen=i;}else if(rc[i]==23){result=23;goto done;}}
 if(mode!=SP_PREPARE&&((slots[0].handle&&(rc[0]==1||rc[0]==2))||(slots[1].handle&&(rc[1]==1||rc[1]==2)))){result=1;goto done;}
 if(owners==2){if(slots[0].binding.base!=slots[1].binding.base||slots[0].binding.table!=slots[1].binding.table){result=SP_AMBIGUOUS;goto done;}owners=1;chosen=0;}
 if(mode==SP_PREPARE){if(owners){result=SP_PROVIDER_EXISTS;goto done;}if(slots[0].handle){result=SP_STARTING;goto done;}if(slots[1].handle&&(rc[1]==1||rc[1]==2)){result=1;goto done;}chosen=1;if(!slots[1].handle){slots[1].handle=p->open(p->context,1,0);if(!slots[1].handle){result=21;goto done;}if(!p->binding(p->context,slots[1].handle,&slots[1].binding)||!binding_ok(&slots[1].binding)){result=SP_BAD_PROVIDER;goto done;}rc[1]=slots[1].binding.table->discover(probe,&slots[1].discovery);if(!description_ok(probe,&slots[1].binding,&slots[1].discovery,rc[1])){result=SP_BAD_PROVIDER;goto done;}if(rc[1]!=21){result=rc[1]?1:SP_PROVIDER_EXISTS;goto done;}}result=0;
 }else{if(!owners){result=(rc[0]==1||rc[0]==2||rc[1]==1||rc[1]==2)?1:21;goto done;}if(mode==SP_CONTROL&&!identity(q,&slots[chosen].discovery.identity)){result=23;goto done;}result=0;}
 if(chosen<2){*out=slots[chosen];slots[chosen].handle=0;slots[chosen].binding=(struct sp_binding){0};}
 done:for(unsigned i=0;i<2;i++)if(sp_release(p,slots+i))out->close_uncertain=1;if(out->close_uncertain){sp_release(p,out);return AS_CLOSE_UNCERTAIN;}return result;}
